%% |prompt context is the text the fake was given| example |a marker passes through| — laws/fakes.lawspec:73
law_prompt_context_is_the_text_the_fake_was_given__a_marker_passes_through() ->
    {Schema, Symbols} = lawspec_data:context(),
    Meta = make_citable_meta(
        [
            <<"chunk-2">>,
            <<"Elixir in Action — Page 3"/utf8>>,
            <<"Processes">>,
            make_present([<<"books/elixir-in-action.pdf">>], Schema)
        ],
        Schema
    ),
    Segments = make_cons_2(
        [make_plain([<<"see ">>], Schema), make_cons_2([make_marker([1], Schema), []], Schema)],
        Schema
    ),
    lawspec_beam_runtime:require(
        law_prompt_context_is_the_text_the_fake_was_given(Schema, Symbols, [Meta, Segments]),
        ?LAW_PROMPT_CONTEXT_IS_THE_TEXT_THE_FAKE_WAS_GIVEN
    ),
    lawspec_beam_runtime:assert_equal(
        lawspec_definitions:cake_laws_shared_render_2(Schema, Symbols, Segments),
        <<"see [1]">>,
        <<"|prompt context is the text the fake was given| example |a marker passes through| — laws/fakes.lawspec:73"/utf8>>
    ),
    lawspec_beam_runtime:assert_equal(
        lawspec_definitions:prompt_context(
            Schema,
            Symbols,
            Meta,
            lawspec_definitions:cake_laws_shared_render_2(Schema, Symbols, Segments)
        ),
        <<"see [1]">>,
        <<"|prompt context is the text the fake was given| example |a marker passes through| — laws/fakes.lawspec:74"/utf8>>
    ).

